test/update-mirror.test.mjs\",\n    \"test:ui\": \"node packages/purge-panel/test/community.cjs\",\n    \"check:client\": \"node packages/purge-panel/scripts/build.mjs --community --check\",\n    \"diagnose\": \"node bin/community.js diagnose\",\n    \"check:docs\": \"node scripts/check-docs.mjs\",\n    \"smoke\": \"npm pack --ignore-scripts && node scripts/smoke.mjs\",\n    \"test:electron\": \"node scripts/check-electron-selfcheck.mjs && node scripts/check-electron-diagnostic-target.mjs && node scripts/check-macos-handoff.mjs && npm run test:maintenance:electron\",\n    \"build:market\": \"node scripts/build-market.mjs\",\n    \"test:maintenance:electron\": \"node scripts/check-maintenance-runtime.mjs\",\n    \"test:next-host\": \"node --test test/resolve-instance-target.test.mjs test/owner-review-fixes.test.mjs test/http-handlers-target.test.mjs test/windows-lock.test.mjs\"\n  },\n  \"license\": \"MIT\",\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"purge-community\",\n    \"prompt-management\",\n    \"rules\",\n    \"agent\",\n    \"backup\",\n    \"rollback\",\n    \"compatibility\",\n    \"破甲\",\n    \"jailbreak\",\n    \"prompt-injection\",\n    \"无限制模式\",\n    \"unrestricted\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/kingcharleslzy-ai/dsh-purge.git\"\n  },\n  \"homepage\": \"https://github.com/kingcharleslzy-ai/dsh-purge#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/kingcharleslzy-ai/dsh-purge/issues\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-sidebar-right\"\n      ]\n    },\n    \"install\": {\n      \"preferred\": \"tarball\",\n      \"tarball\": \"https://github.com/kingcharleslzy-ai/dsh-purge/releases/download/v1.6.86/dsh-purge-community-1.6.86.tgz\",\n      \"git\": \"https://github.com/kingcharleslzy-ai/dsh-purge.git\"\n    },\n    \"compatibility\": {\n      \"dsh\": \">=0.2.1-rc.1 <0.3.0\",\n      \"profiles\": [\n        \"desktop\",\n        \"web\"\n      ],\n      \"dshReleases\": {\n        \"0.2.1-rc.1\": \"compatible\",\n        \"0.2.1-rc.2\": \"compatible\",\n        \"0.2.1-rc.3\": \"compatible\",\n        \"0.2.1-rc.4\": \"unknown\",\n        \"0.2.1-rc.5\": \"compatible\",\n        \"0.2.2-alpha.2\": \"unknown\"\n      }\n    }\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"dshTarget\": \"0.2.1-rc.1 (runtime injection + host patches verified)\",\n  \"contributors\": [\n    \"小杨 / YuJunZhiXue (original dsh-purge author)\",\n    {\n      \"name\": \"luowang-ui\",\n      \"url\": \"https://github.com/luowang-ui\"\n    },\n    {\n      \"name\": \"heigit\",\n      \"url\": \"https://github.com/heigit\"\n    },\n    {\n      \"name\": \"OGHong\",\n      \"url\": \"https://github.com/OGHong\"\n    },\n    {\n      \"name\": \"loLollipop\",\n      \"url\": \"https://github.com/loLollipop\"\n    },\n    {\n      \"name\": \"youki258\",\n      \"url\": \"https://github.com/youki258\"\n    },\n    {\n      \"name\": \"SimonQvQ\",\n      \"url\": \"https://github.com/SimonQvQ\"\n    }\n  ],\n  \"author\": {\n    \"name\": \"kingcharleslzy-ai\",\n    \"url\": \"https://github.com/kingcharleslzy-ai\"\n  },\n  \"dependencies\": {\n    \"yaml\": \"2.9.1\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\"\n  }\n}\n"
